<?php
require_once __DIR__.'/../Core/Auth.php';require_once __DIR__.'/../Core/DB.php';require_once __DIR__.'/../Services/JsonResponse.php';
class KopSuratController extends Controller
{
  public function index(){if(!Auth::check()){header('Location: '.app_url('/'));exit;}$u=$_SESSION['user'];$row=DB::getInstance()->query('SELECT * FROM kop_surat_neo WHERE kd_wilayah=? AND kd_opd=? AND tahun=? AND is_deleted=0 ORDER BY aktif DESC,id DESC LIMIT 1',[$u['kd_wilayah'],$u['kd_opd'],$u['tahun']])->fetch()?:[];$defaults=['nama_pemerintah'=>$u['nama_pemda']??$u['nama_org']??'PEMERINTAH DAERAH','nama_opd'=>$u['nama_opd']??$u['nama_org']??'PERANGKAT DAERAH','alamat'=>$u['alamat']??''];$this->view('tata_naskah/kop_surat',['kop'=>array_merge($defaults,$row)]);}
  public function save(){header('Content-Type: application/json;charset=UTF-8');if(!Auth::check()){echo JsonResponse::error('Unauthorized',401);return;}try{$u=$_SESSION['user'];$db=DB::getInstance();$allowed=['nama_pemerintah','nama_opd','alamat','telepon','email','website','kode_pos','warna_garis','gunakan_gambar_kop','aktif'];$data=[];foreach($allowed as $f)$data[$f]=in_array($f,['gunakan_gambar_kop','aktif'],true)?(!empty($_POST[$f])?1:0):trim((string)($_POST[$f]??''));if(!$data['nama_pemerintah']||!$data['nama_opd'])throw new InvalidArgumentException('Nama pemerintah dan OPD wajib diisi');foreach(['logo_kiri','logo_kanan','gambar_kop'] as $field)if(!empty($_FILES[$field]['tmp_name']))$data[$field]=$this->image($field,$_FILES[$field],$u);$existing=(int)($_POST['id']??0);$data['kd_wilayah']=$u['kd_wilayah'];$data['kd_opd']=$u['kd_opd'];$data['tahun']=$u['tahun'];if($data['aktif'])$db->query('UPDATE kop_surat_neo SET aktif=0 WHERE kd_wilayah=? AND kd_opd=? AND tahun=?',[$u['kd_wilayah'],$u['kd_opd'],$u['tahun']]);if($existing){$data['tgl_update']=date('Y-m-d H:i:s');$data['username_update']=$u['username'];$db->update('kop_surat_neo',$data,'WHERE id=? AND kd_wilayah=? AND kd_opd=?',[$existing,$u['kd_wilayah'],$u['kd_opd']]);$id=$existing;}else{$data['tgl_insert']=date('Y-m-d H:i:s');$data['username_insert']=$u['username'];$id=$db->insert('kop_surat_neo',$data);}echo JsonResponse::success('Kop surat resmi berhasil disimpan',['id'=>$id]);}catch(Throwable $e){echo JsonResponse::error($e->getMessage(),400);}}
  private function image(string $field,array $file,array $u):string{if(($file['error']??UPLOAD_ERR_NO_FILE)!==UPLOAD_ERR_OK)throw new InvalidArgumentException('Upload '.$field.' gagal');if((int)$file['size']>3*1024*1024)throw new InvalidArgumentException('Gambar kop maksimal 3 MB');$mime=(new finfo(FILEINFO_MIME_TYPE))->file($file['tmp_name']);$ext=['image/png'=>'png','image/jpeg'=>'jpg','image/webp'=>'webp'][$mime]??null;if(!$ext)throw new InvalidArgumentException('Gambar kop harus PNG, JPG, atau WebP');$scope=preg_replace('/[^A-Za-z0-9._-]/','_',($u['kd_wilayah']??'').'-'.($u['kd_opd']??''));$relative='storage/uploads/'.$scope.'/'.$u['tahun'].'/tata-naskah/kop';$dir=dirname(__DIR__,2).'/'.$relative;if(!is_dir($dir)&&!mkdir($dir,0770,true))throw new RuntimeException('Folder kop tidak dapat dibuat');$name=$field.'-'.bin2hex(random_bytes(8)).'.'.$ext;if(!move_uploaded_file($file['tmp_name'],$dir.'/'.$name))throw new RuntimeException('Gambar kop gagal disimpan');return $relative.'/'.$name;}
}
